# Surah Al-Kahf (chapter 18) — part 6: ayat 51-60 (IDs 2191-2200)
SURAH = 18

ENTRIES = {
2191: (
"میں نے انہیں آسمانوں اور زمین کی تخلیق پر گواہ نہیں بنایا اور نہ ان کی اپنی تخلیق پر — اور میں گمراہ کرنے والوں کو اپنا معاون نہیں بناتا",
"""۱۔ اللہ — تنہا خالق؛ کسی کا ساجھا نہیں؛ شیطان کو مددگار نہیں بناتا۔
۲۔ ’’مَّا أَشْهَدتُّهُمْ خَلْقَ السَّمَاوَاتِ وَالْأَرْضِ وَلَا خَلْقَ أَنفُسِهِمْ وَمَا كُنتُ مُتَّخِذَ الْمُضِلِّينَ عَضُدًا‘‘ — میں نے انہیں آسمانوں اور زمین کی تخلیق پر گواہ نہیں بنایا اور نہ ان کی اپنی تخلیق پر — اور میں گمراہ کرنے والوں کو اپنا معاون نہیں بناتا — یعنی میں نے انہیں آسمانوں اور زمین کی تخلیق میں شامل نہیں کیا اور نہ ان کی اپنی تخلیق میں اور میں گمراہ کرنے والوں کو اپنا دستِ راست نہیں بناتا۔
۳۔ عملی سبق: اللہ ہی خالق ہے؛ گمراہ کرنے والوں کی پیروی نہ کرو؛ اسی پر بھروسہ کرو۔"""
),
2192: (
"اور جس دن وہ کہے گا پکارو میرے ان شریکوں کو جنہیں تم نے گمان کیا تھا — پس وہ انہیں پکاریں گے مگر وہ انہیں جواب نہیں دیں گے — اور ہم ان کے درمیان ایک تباہ کن وادی رکھیں گے",
"""۱۔ قیامت میں مشرکوں کے ٹھہرائے ہوئے معبود گم ہو جائیں گے؛ کوئی جواب نہیں؛ تباہ کن وادی۔
۲۔ ’’وَيَوْمَ يَقُولُ نَادُوا شُرَكَائِيَ الَّذِينَ زَعَمْتُمْ فَدَعَوْهُمْ فَلَمْ يَسْتَجِيبُوا لَهُمْ وَجَعَلْنَا بَيْنَهُم مَّوْبِقًا‘‘ — اور جس دن وہ کہے گا پکارو میرے ان شریکوں کو جنہیں تم نے گمان کیا تھا — پس وہ انہیں پکاریں گے مگر وہ انہیں جواب نہیں دیں گے — اور ہم ان کے درمیان ایک تباہ کن وادی رکھیں گے — یعنی جس دن وہ کہے گا پکارو ان شریکوں کو جنہیں تم نے گمان کیا تھا — پس انہوں نے انہیں پکارا مگر وہ جواب نہ دے سکے — اور ہم نے ان کے درمیان ایک ہلاکت کی وادی رکھ دی۔
۳۔ عملی سبق: دنیا کی معبودیاں بے بس ہو جائیں گی؛ صرف اللہ پر بھروسہ کرو۔"""
),
2193: (
"اور مجرمین آگ کو دیکھیں گے پس گمان کریں گے کہ وہ اس میں گرنے والے ہیں — اور اس سے بھاگنے کی کوئی جگہ نہ پائیں گے",
"""۱۔ مجرموں کو جہنم نظر آئے گا؛ انجام یقینی؛ کوئی مہربانی نہ ملے گی۔
۲۔ ’’وَرَأَى الْمُجْرِمُونَ النَّارَ فَظَنُّوا أَنَّهُم مُّوَاقِعُوهَا وَلَمْ يَجِدُوا عَنْهَا مَصْرِفًا‘‘ — اور مجرمین آگ کو دیکھیں گے پس گمان کریں گے کہ وہ اس میں گرنے والے ہیں — اور اس سے بھاگنے کی کوئی جگہ نہ پائیں گے — یعنی مجرم جہنم کو دیکھیں گے پس سمجھیں گے کہ وہ اسی میں گرنے والے ہیں — اور اس سے ایک ذرہ بھاگنے کی جگہ نہ پائیں گے۔
۳۔ عملی سبق: جہنم کی آگ سے بچو؛ گناہوں سے بچو؛ اللہ کی رحمت مانگو۔"""
),
2194: (
"اور یقیناً ہم نے اس قرآن میں لوگوں کے لیے ہر قسم کی مثالیں بیان کیں — اور انسان سب سے زیادہ جھگڑالو چیز ہے",
"""۱۔ قرآن میں ہر قسم کی مثالیں؛ مگر انسان گمراہ جھگڑالو ہے۔
۲۔ ’’وَلَقَدْ صَرَّفْنَا فِي هَٰذَا الْقُرْآنِ لِلنَّاسِ مِن كُلِّ مَثَلٍ وَكَانَ الْإِنسَانُ أَكْثَرَ شَيْءٍ جَدَلًا‘‘ — اور یقیناً ہم نے اس قرآن میں لوگوں کے لیے ہر قسم کی مثالیں بیان کیں — اور انسان سب سے زیادہ جھگڑالو چیز ہے — یعنی ہم نے اس قرآن میں لوگوں کے لیے ہر قسم کی مثالیں بیان کیں — اور انسان سب سے زیادہ جھگڑالو چیز ہے۔
۳۔ عملی سبق: قرآن سمجھنے کے لیے دل نرم کرو؛ جھگڑالو پن سے بچو۔"""
),
2195: (
"اور لوگوں کو ایمان لانے اور اپنے رب سے مغفرت مانگنے سے کیا چیز مانع ہے جب ان کے پاس ہدایت آئی سوائے اس کے کہ ان پر پہلے لوگوں کا عذاب آئے یا ان کے پاس واضح عذاب آئے",
"""۱۔ ہدایت آ جانے کے بعد بھی انکار — پہلے لوگوں کا عذاب دہرایا جائے گا؛ یا سامنے عذاب۔
۲۔ ’’وَمَا مَنَعَ النَّاسَ أَن يُؤْمِنُوا إِذْ جَاءَهُمُ الْهُدَىٰ وَيَسْتَغْفِرُوا رَبَّهُمْ إِلَّا أَن تَأْتِيَهُمْ سُنَّۃُ الْأَوَّلِينَ أَوْ يَأْتِيَهُمُ الْعَذَابُ قُبُلًا‘‘ — اور لوگوں کو ایمان لانے اور اپنے رب سے مغفرت مانگنے سے کیا چیز مانع ہے جب ان کے پاس ہدایت آئی سوائے اس کے کہ ان پر پہلے لوگوں کا عذاب آئے یا ان کے پاس واضح عذاب آئے — یعنی ہدایت آ جانے کے بعد ایمان نہ لائے مگر صرف اس لیے کہ ان کے پاس پہلے لوگوں کا عذاب آئے یا سامنے عذاب پہنچے۔
۳۔ عملی سبق: ہدایت پا کر فوراً ایمان لاؤ؛ عذاب آنے کا انتظار نہ کرو۔"""
),
2196: (
"اور ہم پیغمبروں کو صرف خوشخبری دینے والے اور ڈرانے والے بنا کر بھیجتے ہیں — اور کافر لوگ باطل طریقے سے جھگڑتے ہیں تاکہ اس سے حق کو مٹا دیں — اور انہوں نے میری آیات اور جو انہیں ڈرایا گیا اسے مذاق بنا لیا",
"""۱۔ انبیاؑ بشارت و انذار کے حامل ہیں؛ کفار باطل سے حق کو مٹانے کی کوشش کرتے ہیں؛ آیات کا مذاق بناتے ہیں۔
۲۔ ’’وَمَا نُرْسِلُ الْمُرْسَلِينَ إِلَّا مُبَشِّرِينَ وَمُنذِرِينَ وَيُجَادِلُ الَّذِينَ كَفَرُوا بِالْبَاطِلِ لِيُدْحِضُوا بِهِ الْحَقَّ وَاتَّخَذُوا آيَاتِي وَمَا أُنذِرُوا هُزُوًا‘‘ — اور ہم پیغمبروں کو صرف خوشخبری دینے والے اور ڈرانے والے بنا کر بھیجتے ہیں — اور کافر لوگ باطل طریقے سے جھگڑتے ہیں تاکہ اس سے حق کو مٹا دیں — اور انہوں نے میری آیات اور جو انہیں ڈرایا گیا اسے مذاق بنا لیا — یعنی ہم پیغمبروں کو صرف بشارت اور انذار کے لیے بھیجتے ہیں اور کافر باطل کے ساتھ جھگڑتے ہیں تاکہ حق کو مٹا سکیں اور انہوں نے میری آیات اور ڈرانے والی باتوں کو مذاق بنا لیا۔
۳۔ عملی سبق: حق کے سامنے باطل بے بس ہے؛ آیات کو مذاق نہ بناؤ۔"""
),
2197: (
"اور اس سے بڑھ کر ظالم کون ہے جسے اس کے رب کی آیات سے نصیحت کی جائے پھر وہ ان سے منہ موڑ لے — اور بھول جائے جو اس کے ہاتھوں نے آگے بھیجا — بے شک ہم نے ان کے دلوں پر پردہ ڈال دیا ہے کہ وہ اسے نہ سمجھ سکیں — اور ان کے کانوں میں بھاری پن — اگر تم انہیں ہدایت کی طرف بلاؤ تب بھی وہ کبھی ہدایت نہ پائیں گے",
"""۱۔ نصیحت پا کر منہ موڑنے والا سب سے بڑا ظالم؛ اللہ دل اور کان بند کر دیتا ہے؛ ہدایت نہ ملے۔
۲۔ ’’وَمَنْ أَظْلَمُ مِمَّن ذُكِّرَ بِآيَاتِ رَبِّهِ فَأَعْرَضَ عَنْهَا وَنَسِيَ مَا قَدَّمَتْ يَدَاهُ إِنَّا جَعَلْنَا عَلَىٰ قُلُوبِهِمْ أَكِنَّۃً أَن يَفْقَهُوهُ وَفِي آذَانِهِمْ وَقْرًا وَإِن تَدْعُهُمْ إِلَى الْهُدَىٰ فَلَن يَهْتَدُوا إِذًا أَبَدًا‘‘ — اور اس سے بڑھ کر ظالم کون ہے جسے اس کے رب کی آیات سے نصیحت کی جائے پھر وہ ان سے منہ موڑ لے — اور بھول جائے جو اس کے ہاتھوں نے آگے بھیجا — بے شک ہم نے ان کے دلوں پر پردہ ڈال دیا ہے کہ وہ اسے نہ سمجھ سکیں — اور ان کے کانوں میں بھاری پن — اگر تم انہیں ہدایت کی طرف بلاؤ تب بھی وہ کبھی ہدایت نہ پائیں گے — یعنی اس سے بڑا ظالم کون ہے جسے اس کے رب کی آیات سے نصیحت کی جائے پھر وہ ان سے منہ موڑ لے اور بھول جائے جو اس کے ہاتھوں نے آگے بھیجا — ہم نے ان کے دلوں پر پردے ڈال دیئے اور ان کے کانوں میں بھاری پن — اور اگر تم انہیں ہدایت کی طرف بلاؤ تو وہ ہرگز ہدایت نہ پائیں گے۔
۳۔ عملی سبق: آیاتِ الٰہی سن کر عمل کرو؛ نصیحت سے منہ موڑنا بڑی برائی ہے۔"""
),
2198: (
"اور آپ کا رب درگزر کرنے والا رحمت والا ہے — اگر وہ ان کے کرتوت کے بدلے انہیں پکڑے تو ان پر عذاب میں جلدی کرے — بلکہ ان کے لیے ایک مقررہ وقت ہے جس سے وہ کبھی نہیں بھاگ سکتے",
"""۱۔ اللہ درگزر کرنے والا ہے؛ مگر اس کا مقررہ وقت آئے گا؛ کوئی چھٹکارا نہیں۔
۲۔ ’’وَرَبُّكَ الْغَفُورُ ذُو الرَّحْمَۃِ لَوْ يُؤَاخِذُهُم بِمَا كَسَبُوا لَعَجَّلَ لَهُمُ الْعَذَابَ بَل لَّهُم مَّوْعِدٌ لَّن يَجِدُوا مِن دُونِهِ مَوْئِلًا‘‘ — اور آپ کا رب درگزر کرنے والا رحمت والا ہے — اگر وہ ان کے کرتوت کے بدلے انہیں پکڑے تو ان پر عذاب میں جلدی کرے — بلکہ ان کے لیے ایک مقررہ وقت ہے جس سے وہ کبھی نہیں بھاگ سکتے — یعنی آپ کا رب بخشنے والا رحمت والا ہے — اگر وہ ان کے اعمال کے بدلے فوری عذاب دے تو جلدی کر دے مگر ان کے لیے ایک مقررہ وقت ہے جس سے وہ نہیں بھاگ سکتے۔
۳۔ عملی سبق: اللہ کی رحمت پر بھروسہ رکھو؛ مگر اس کے فیصلے سے بچو نہیں سکتے۔"""
),
2199: (
"اور وہ آبادیاں جنہیں ہم نے ظلم کے وقت ہلاک کیا — اور ہم نے ان کی ہلاکت کے لیے ایک مقررہ وقت رکھا",
"""۱۔ قوموں کی تباہی — ظلم پر؛ ہر قوم کا مقررہ وقت تھا؛ اللہ کا فیصلہ۔
۲۔ ’’وَتِلْكَ الْقُرَىٰ أَهْلَكْنَاهُمْ لَمَّا ظَلَمُوا وَجَعَلْنَا لِمَهْلِكِهِم مَّوْعِدًا‘‘ — اور وہ آبادیاں جنہیں ہم نے ظلم کے وقت ہلاک کیا — اور ہم نے ان کی ہلاکت کے لیے ایک مقررہ وقت رکھا — یعنی وہ آبادیاں جنہیں ہم نے ہلاک کیا جب انہوں نے ظلم کیا اور ہم نے ان کی تباہی کے لیے مقررہ وقت رکھا۔
۳۔ عملی سبق: ظلم سے بچو؛ اللہ کی ڈھیل کا مطلب عفو نہیں۔"""
),
2200: (
"اور جب موسیٰؑ نے اپنے جوان ساتھی سے کہا میں اس وقت تک نہیں رکوں گا جب تک دونوں سمندروں کے سنگم تک نہ پہنچ جاؤں چاہے میں لاکھوں سال سفر کرتا رہوں",
"""۱۔ موسیٰؑ کا عزم — اللہ کے علم کے پہنچنے کا؛ گل گشتہ علمِ الہٰی کی تلاش میں۔
۲۔ ’’وَإِذْ قَالَ مُوسَىٰ لِفَتَاهُ لَا أَبْرَحُ حَتَّىٰ أَبْلُغَ مَجْمَعَ الْبَحْرَيْنِ أَوْ أَمْضِيَ حُقُبًا‘‘ — اور جب موسیٰؑ نے اپنے جوان ساتھی سے کہا میں اس وقت تک نہیں رکوں گا جب تک دونوں سمندروں کے سنگم تک نہ پہنچ جاؤں چاہے میں لاکھوں سال سفر کرتا رہوں — یعنی جب موسیٰ نے اپنے ساتھی سے کہا میں سفر جاری رکھوں گا یہاں تک کہ دونوں سمندروں کے سنگم تک پہنچ جاؤں یا نہ جانے کتنا عرصہ چلتا رہوں۔
۳۔ عملی سبق: علم کی تلاش میں سفر کرو؛ اللہ سےعلم حاصل کرنے کی جستجو کرو۔"""
),
}
